  function capPath(profile,cx,top){const w=profile.width,h=profile.height,x=cx-w/2,y=top,b=x+w;switch(profile.shape){case"chamfer":return `M${x+4} ${y} H${b-4} L${b} ${y+4} V${y+h-4} L${b-4} ${y+h} H${x+4} L${x} ${y+h-4} V${y+4}Z`;case"hex":return `M${x+5} ${y} H${b-5} L${b} ${y+8} V${y+h-8} L${b-5} ${y+h} H${x+5} L${x} ${y+h-8} V${y+8}Z`;case"taper":return `M${x+3} ${y} H${b-3} L${b} ${y+h-8} L${b-4} ${y+h} H${x+4} L${x} ${y+h-8}Z`;case"notch":return `M${x} ${y} H${b} V${y+12} L${b-4} ${y+16} L${b} ${y+20} V${y+h} H${x} V${y+20} L${x+4} ${y+16} L${x} ${y+12}Z`;case"shield":return `M${x+3} ${y} H${b-3} L${b} ${y+5} V${y+h-14} Q${cx} ${y+h} ${cx} ${y+h} Q${x} ${y+h-14} ${x} ${y+h-14} V${y+5}Z`;case"dogtag":return `M${x+4} ${y} H${b-4} Q${b} ${y} ${b} ${y+4} V${y+h-4} Q${b} ${y+h} ${b-4} ${y+h} H${x+4} Q${x} ${y+h} ${x} ${y+h-4} V${y+4} Q${x} ${y} ${x+4} ${y}Z`;case"waist":return `M${x} ${y} H${b} L${b-3} ${y+12} L${b} ${y+24} V${y+h} H${x} V${y+24} L${x+3} ${y+12}Z`;default:return `M${x+profile.radius} ${y} H${b-profile.radius} Q${b} ${y} ${b} ${y+profile.radius} V${y+h-profile.radius} Q${b} ${y+h} ${b-profile.radius} ${y+h} H${x+profile.radius} Q${x} ${y+h} ${x} ${y+h-profile.radius} V${y+profile.radius} Q${x} ${y} ${x+profile.radius} ${y}Z`;}}
  function liveKeyCapMarkup(profile,rotation){const cx=60,top=22,w=profile.width,h=profile.height,x=cx-w/2;return `<g data-key-cap data-key-base-rotation="${rotation}" transform="rotate(${rotation} ${cx} ${top+h/2})"><path d="${capPath(profile,cx,top)}" fill="${profile.edge}"/><path d="${capPath({...profile,width:Math.max(10,w-5),height:h-6,radius:Math.max(1,profile.radius-1)},cx,top+3)}" fill="${profile.face}" stroke="${profile.highlight}" stroke-width="1.5"/><path d="M${cx-4} ${top+9} H${cx+4} M${cx-4} ${top+14} H${cx+3}" stroke="${profile.highlight}" stroke-width="1.4" opacity=".7"/>${profile.shape==="ribbed"?`<path d="M${x+4} ${top+20} H${x+w-4} M${x+4} ${top+25} H${x+w-4} M${x+4} ${top+30} H${x+w-4}" stroke="${profile.highlight}" opacity=".55"/>`:""}<circle cx="${cx}" cy="${top+h-5}" r="3.4" fill="${profile.edge}" stroke="${profile.highlight}" stroke-width="1.3"/></g>`;}
  function manualKeyCapMarkup(profile,rotation){const scale=1.05,cx=90,top=23,scaled={...profile,width:profile.width*scale,height:Math.min(51,profile.height*.92),radius:profile.radius};const h=scaled.height;return `<circle class="ink-line" cx="90" cy="48" r="31"/><g transform="rotate(${rotation} ${cx} ${top+h/2})"><path class="ink-solid" d="${capPath(scaled,cx,top)}"/><path class="paper-hole" d="${capPath({...scaled,width:Math.max(9,scaled.width-5),height:h-6,radius:Math.max(1,scaled.radius-1)},cx,top+3)}"/><path class="ink-line" d="M${cx-4} ${top+10} H${cx+4} M${cx-4} ${top+15} H${cx+3}"/><circle class="ink-solid" cx="${cx}" cy="${top+h-5}" r="3"/></g>`;}
  function manualCharmMarkup(charm){return `<g transform="translate(119 64) scale(.58)">${charmShapeMarkup(charm,true)}</g>`;}
  function manualKeyCapBody(rotation){const loadout=keyLoadout(activeStation),profile=loadout.cap;return `${manualKeyCapMarkup(profile,rotation)}<line class="ink-line" x1="101" y1="70" x2="114" y2="77"/>${manualCharmMarkup(loadout.charm)}`;}
  function manualAuthSnapshotMarkup(token,def){const identity=authIdentity(activeStation,token);let body="",stateLabel="";if(token==="auth-key-insert"){stateLabel="CAP SEATED / SAFE";body=manualKeyCapBody(-34);}else if(token==="auth-key-arm"){stateLabel="CAP ROTATED TO ARM";body=manualKeyCapBody(34)+`<text class="snapshot-tiny" x="135" y="28">ARM</text>`;}else if(token==="auth-shield-open"){stateLabel="SAFETY SHIELD FULLY BACK";body=`<rect class="ink-line" x="55" y="30" width="70" height="46"/><rect class="ink-solid" x="69" y="42" width="42" height="25"/><path class="ink-heavy" d="M55 30 L49 20 L131 20 L125 30"/><text class="snapshot-tiny paper-text" x="90" y="57" text-anchor="middle">EXECUTE</text>`;}else{stateLabel=`${def.execute} — DEPRESSED`;body=`<rect class="ink-heavy" x="55" y="26" width="70" height="52"/><rect class="ink-solid" x="65" y="38" width="50" height="28"/><text class="snapshot-tiny paper-text" x="90" y="55" text-anchor="middle">EXECUTE</text><line class="ink-heavy" x1="69" y1="72" x2="111" y2="72"/>`;}return {identity,stateLabel,markup:snapshotSvg(body,stateLabel)};}
  function manualStepWithFigure(token,def,index){const text=tokenLabel(token,def);let code="CONTROL",label="CONTROL",stateLabel="SET",markup="",figureClass="";if(AUTH_TAIL.includes(token)){const auth=manualAuthSnapshotMarkup(token,def);code=auth.identity.code;label=auth.identity.label;stateLabel=auth.stateLabel;markup=auth.markup;figureClass=" snapshot-auth";}else{const hit=findAction(def,token);if(hit){const identity=controlIdentity(activeStation,hit.ctrl);code=identity.code;label=identity.label;stateLabel=hit.action.label;markup=manualControlSnapshotMarkup(hit.ctrl,hit.action);figureClass=` snapshot-kind-${hit.ctrl.kind} physical-${hit.ctrl.physical||hit.ctrl.kind}`;}}return `<li><b>${index+1}</b><div class="exo-manual-step-block" style="display:flex;flex-wrap:wrap;gap:10px 14px;align-items:flex-start"><div style="flex:1 1 420px;min-width:0">${manualStepMarkup(text)}</div>${markup?`<figure class="exo-manual-figure${figureClass}" data-manual-control-code="${code}" style="flex:0 1 180px;width:180px;max-width:100%;margin:0;padding:5px;border:1px solid #756d5c;background:rgba(238,230,211,.72)"><div class="exo-manual-snapshot">${markup}</div><figcaption style="margin-top:4px;color:#28241d;font:700 .52rem/1.25 Courier New,monospace;text-transform:uppercase"><span style="display:block">FIGURE ${index+1}</span><b>${code}</b> — ${label}<small style="display:block;margin-top:2px;font-size:.48rem">REQUIRED POSITION: ${stateLabel}</small></figcaption></figure>`:""}</div></li>`;}
  window.EXO_CONTROL_CATALOG=CONTROL_CATALOG;

  const CONTROL_DEFAULTS=Object.freeze({
    helm:{"flight-mode":"ATTITUDE","thruster-bank":"MAIN DRIVE","trim-wheel":"CENTERED","translation-throttle":"NOMINAL","thrust-gate":"HOLD"},
    navigation:{"nav-reference":"INERTIAL","azimuth-drum":"AZ ZERO","elevation-drum":"EL ZERO","delta-v":"NOMINAL","timebase":"LOCKED","solution-latch":"HOLD"},
    gunnery:{"weapon-safe":"GUARD CLOSED","weapon-bank":"COIL A","range-gate":"CENTERED","capacitor":"READY","weapon-arm":"SAFE"},
    engineering:{"rectifier-a":"NOMINAL","rectifier-b":"NOMINAL","rectifier-c":"NOMINAL","rectifier-d":"NOMINAL","bus-transfer":"PRIMARY","voltage-a":"NOMINAL","voltage-b":"NOMINAL","breaker-reactor":"ON","breaker-rectifier":"ON","breaker-coolant":"ON","breaker-grid":"ON","breaker-field":"ON","breaker-inverter":"ON","breaker-sensor":"ON","breaker-lighting":"ON","coolant-valve":"METERED","pump-select":"A"},
    science:{"receiver-band":"WIDEBAND","aperture":"MAIN ARRAY","receiver-gain":"NOMINAL","integration":"NOMINAL","emitter-inhibit":"CLOSED","emitter-gate":"SAFE"},
    comms:{"link-mode":"HAIL","carrier-path":"OMNI RF","channel-wheel":"HOME","frequency":"CENTERED","tx-power":"NOMINAL","crypto":"CLEAR","transmit-key":"SAFE","squelch":"NOMINAL"}
  });
  const RESET_AFTER_EXECUTE=Object.freeze({helm:{"thrust-gate":"HOLD"},navigation:{"solution-latch":"HOLD"},science:{"emitter-gate":"SAFE"},comms:{"transmit-key":"SAFE"}});
  const MOMENTARY_KINDS=new Set(["dual-button","yoke"]);
  const GESTURE_KINDS=new Set(["selector","rotary","wheel","yoke","thumbwheel","lever","knife-switch","toggle","guard","dual-slider"]);
  function controlMode(station,ctrl){if(MOMENTARY_KINDS.has(ctrl.kind))return "momentary";if(RESET_AFTER_EXECUTE[station]?.[ctrl.id]!==undefined)return "reset-execute";return "latched";}
  const controlAudio=()=>window.EXO_CONTROL_AUDIO||null;
  const CONTROL_SOUND_SCENE=Object.freeze({selector:"selector-set",rotary:"rotary-detent",wheel:"wheel-stop",thumbwheel:"thumbwheel-notch",lever:"lever-throw","knife-switch":"knife-throw",toggle:"toggle-flick",guard:"guard-cover","dual-slider":"servo-set",slider:"servo-set",yoke:"yoke-return",keypad:"button-light",matrix:"button-light","switch-bank":"toggle-flick","breaker-bank":"breaker-throw","dual-button":"button-heavy",lockout:"key-turn"});
  function controlSoundScene(token,controlId){if(token==="auth-key-insert")return "key-insert";if(token==="auth-key-arm")return "key-turn";if(token==="auth-shield-open")return "guard-cover";if(token==="execute")return "execute-heavy";const def=STATIONS[activeStation],ctrl=controlId?def.controls.find(c=>c.id===controlId):null;return CONTROL_SOUND_SCENE[ctrl?.kind]||"button-light";}
  function playControlSound(token,controlId){const audio=controlAudio();if(!audio)return;const scene=controlSoundScene(token,controlId);audio.play(scene,{seed:`${activeStation}:${token}:${controlId||"auth"}`});if(token.startsWith("com-address")||token.startsWith("com-crypto-ack"))setTimeout(()=>audio.play("electrical-confirm",{seed:`confirm:${token}`,intensity:.8}),88);}
  function motionSoundScene(kind){if(["selector","rotary","wheel","thumbwheel"].includes(kind))return "detent-roll-loop";if(["dual-slider","yoke"].includes(kind))return "servo-loop";return null;}
  function motionSoundKey(kind,controlId){return `crew:${activeStation}:${controlId||kind}`;}
  function startControlMotionSound(kind,controlId){const scene=motionSoundScene(kind),audio=controlAudio();if(scene&&audio)audio.startLoop(scene,motionSoundKey(kind,controlId),{seed:motionSoundKey(kind,controlId),intensity:kind==="yoke"?.45:.72});}
  function stopControlMotionSound(kind,controlId){controlAudio()?.stopLoop(motionSoundKey(kind,controlId));}
  function initialHardwareState(){return Object.fromEntries(Object.entries(STATIONS).map(([station,def])=>[station,Object.fromEntries(def.controls.map(ctrl=>[ctrl.id,CONTROL_DEFAULTS[station]?.[ctrl.id]??ctrl.default??"STANDBY"]))]));}
  function findAction(def,token){for(const ctrl of def.controls){const a=ctrl.actions.find(x=>x.token===token);if(a)return {ctrl,action:a};}return null;}
  function requiredStateTargets(station,proc){const def=STATIONS[station],byControl=new Map();for(const token of proc.sequence){if(AUTH_TAIL.includes(token))continue;const hit=findAction(def,token);if(hit&&controlMode(station,hit.ctrl)!=="momentary")byControl.set(hit.ctrl.id,{controlId:hit.ctrl.id,state:hit.action.state,token,label:controlIdentity(station,hit.ctrl).fullName});}return [...byControl.values()];}
  function deriveExpectedSequence(station,proc,startHardware){const def=STATIONS[station],expected=[],preSatisfied=[];for(const token of proc.sequence){if(AUTH_TAIL.includes(token)){expected.push(token);continue;}const hit=findAction(def,token);if(!hit){expected.push(token);continue;}const mode=controlMode(station,hit.ctrl);if(mode!=="momentary"&&startHardware[hit.ctrl.id]===hit.action.state)preSatisfied.push(token);else expected.push(token);}return {expected,preSatisfied,requiredPersistent:requiredStateTargets(station,proc)};}
